<?php
require_once __DIR__.'/../includes/auth.php';
$u=require_role('customer');$pg=pagination_window(20,40);$success=flash('success');release_session_lock();
$sql="SELECT r.id,r.category_id,r.service_id,r.request_type,r.title,r.location_text,r.preferred_date,r.status,r.created_at,c.name category_name,s.name service_name,COALESCE(p.name,b.name,'Open requirement') target_name
FROM service_requests r JOIN categories c ON c.id=r.category_id LEFT JOIN services s ON s.id=r.service_id LEFT JOIN users p ON p.id=r.provider_id LEFT JOIN users b ON b.id=r.business_id
WHERE r.customer_id=? ORDER BY r.created_at DESC,r.id DESC LIMIT ".($pg['per']+1)." OFFSET ".$pg['offset'];
$q=db()->prepare($sql);$q->execute([(int)$u['id']]);$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);$pageTitle='My Service Requests — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="fw-bold mb-1">My Service Requests</h1><p class="text-muted mb-0">Track direct requests and posted requirements.</p></div><a class="btn btn-primary" href="<?=e(base_url('post-requirement.php'))?>">Post a Requirement</a></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if(!$rows):?><div class="soft-card text-center p-5"><i class="fa-regular fa-folder-open fa-3x text-muted mb-3"></i><h3>No service requests on this page.</h3><p class="text-muted">Find a provider or post an open requirement.</p><a class="btn btn-primary" href="<?=e(base_url('search.php'))?>">Browse Services</a></div><?php else:?><div class="row g-3"><?php foreach($rows as $r):?><div class="col-12"><div class="soft-card p-4"><div class="d-flex justify-content-between gap-3"><div><div class="small text-muted"><?=e($r['request_type']==='requirement'?'Posted requirement':$r['target_name'])?> · <?=e($r['category_name'])?></div><h3 class="h5 mb-1"><?=e($r['title'])?></h3><div class="text-muted"><?=e($r['location_text'])?><?php if($r['preferred_date']):?> · <?=e(date('d M Y',strtotime($r['preferred_date'])))?><?php endif;?></div></div><span class="badge request-status status-<?=e($r['status'])?> align-self-start"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></div><div class="mt-3"><a class="btn btn-sm btn-outline-primary" href="<?=e(base_url('request-details.php?id='.$r['id']))?>">View & Track</a></div></div></div><?php endforeach;?></div><?=pagination_nav($pg['page'],$hasNext)?><?php endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
